+++ b/src/taskBoard.ts
@@ -20,6 +20,7 @@ export class TaskBoard {
   private filterState: 'all' | 'active' | 'completed' = 'all';
   private tasks: Task[] = [];
+  private filterButtons: Record<string, HTMLElement> = {};

   constructor(containerId: string) {
     this.container = document.getElementById(containerId);
@@ -52,6 +53,15 @@ export class TaskBoard {
   }

   private filterTasks(): void {
+    const filter = this.filterState;
+    this.tasks.forEach(task => {
+      const item = task.element;
+      if (filter === 'all') item.style.display = 'flex';
+      else if (filter === 'active') item.style.display = task.completed ? 'none' : 'flex';
+      else if (filter === 'completed') item.style.display = task.completed ? 'flex' : 'none';
+    });
   }

